package com.immersio.subscriptions.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="\"PaymentTransactions\"") public class PaymentTransaction { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="\"Id\"") private UUID id; @Column(name="\"TxnRef\"",nullable=false,unique=true) private String txnRef; @Column(name="\"UserId\"",nullable=false) private UUID userId; @Column(name="\"Tier\"",nullable=false) private String tier; @Column(name="\"BillingCycle\"",nullable=false) private String billingCycle; @Column(name="\"Amount\"",nullable=false) private long amount; @Column(name="\"Status\"",nullable=false) private String status="Pending"; @Column(name="\"VnpTransactionNo\"") private String vnpTransactionNo; @Column(name="\"ResponseCode\"") private String responseCode; @Column(name="\"CreatedAt\"",nullable=false) private Instant createdAt=Instant.now(); @Column(name="\"PaidAt\"") private Instant paidAt; protected PaymentTransaction(){} public PaymentTransaction(String ref,UUID u,String t,String c,long a){txnRef=ref;userId=u;tier=t;billingCycle=c;amount=a;} public UUID getId(){return id;} public String getTxnRef(){return txnRef;} public UUID getUserId(){return userId;} public String getTier(){return tier;} public String getBillingCycle(){return billingCycle;} public long getAmount(){return amount;} public String getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public void paid(){status="Paid";paidAt=Instant.now();} public void fail(String code){status="Failed";responseCode=code;} }
